create table private.test_catalog(source_name text,name text,scope_group text,country text,currency text,source text);
insert into private.test_catalog values('RAJA','RAJALOTTERY','IN','印度','INR','ar'),('Shree.Win','SHREEWIN','IN','印度','INR','ar'),('OKWIN','OKWIN','IN','印度','INR','ar'),('OTHER','OTHER','IN','印度','INR','ar'),('HIDDEN','HIDDEN','IN','印度','INR','ar'),('DhaniWin','DHANIWIN','IN','印度','INR','newar'),('MAANWIN','MAAN.WIN','IN','印度','INR','newar'),('FUTURE','FUTURE','IN','印度','INR','newar'),('DISABLED','DISABLED','IN','印度','INR','newar'),('RAJA','RAJALOTTERY','PK','巴基斯坦','PKR','ar');
create function private.dashboard_admin_live_platforms()returns table(source_name text,name text,scope_group text,country text,currency text,source text)language sql stable set search_path=''as $$select *from private.test_catalog$$;
create table public.ar_workorder_issue_details(system_name text not null,country_code text not null,platform text not null,work_order_id text not null,work_order_no text,payment_order_no text,issue_kind text not null,amount numeric(24,8),status_code integer,submitted_date date,submitted_at timestamptz,observed_at timestamptz not null,primary key(system_name,country_code,platform,work_order_id));
create index ar_original_idx on public.ar_workorder_issue_details(country_code,platform,upper(nullif(btrim(payment_order_no),'')))where system_name='AR'and issue_kind='deposit'and payment_order_no is not null;
create table public.newar_detail_platforms(platform text primary key,country_code text not null,country text not null,currency text not null,timezone text not null,enabled boolean not null,launch_at timestamptz);
insert into public.newar_detail_platforms values('DhaniWin','IN','印度','INR','Asia/Kolkata',true,null),('MAANWIN','IN','印度','INR','Asia/Kolkata',true,'2026-10-01T00:00:00Z'),('FUTURE','IN','印度','INR','Asia/Kolkata',true,'2999-01-01T00:00:00Z'),('DISABLED','IN','印度','INR','Asia/Kolkata',false,null);
create table public.newar_detail_records(id uuid primary key,platform text not null,dataset text not null,source_id text not null,amount numeric(24,8)not null,currency text,status_code text,created_at timestamptz not null,captured_at timestamptz not null,workorder_type text,raw jsonb not null check(jsonb_typeof(raw)='object'),unique(platform,dataset,source_id));
create index newar_deposit_idx on public.newar_detail_records(platform,md5(upper(nullif(btrim(raw->>'depositOrderNo'),''))))where dataset='workorder'and workorder_type in('存款未到账','存款未到账自动化')and jsonb_typeof(raw->'depositOrderNo')='string';
create index newar_recharge_idx on public.newar_detail_records(platform,md5(upper(nullif(btrim(raw->>'rechargeNumber'),''))))where dataset='workorder'and workorder_type in('存款未到账','存款未到账自动化')and jsonb_typeof(raw->'rechargeNumber')='string';
alter table public.ar_workorder_issue_details enable row level security;
alter table public.newar_detail_records enable row level security;
alter table public.newar_detail_platforms enable row level security;
revoke all on public.ar_workorder_issue_details,public.newar_detail_records,public.newar_detail_platforms from public,anon,authenticated,service_role;
